static const char *diskNames[2] = { "disk1.img", "disk2.img" };

static unsigned rd16(const uint8_t *p) { return (unsigned)(p[0] | p[1] << 8); }
static uint32_t rd32(const uint8_t *p) { return (uint32_t)(p[0] | p[1] << 8 | p[2] << 16 | (uint32_t)p[3] << 24); }

// dir's file named name in any case: its path
static bool find_in_dir(const char *dir, const char *name, char *path, size_t n)
{
  DIR *d = opendir(dir);
  if (!d) return false;
  bool found = false;
  for (struct dirent *e; !found && (e = readdir(d));)
    if (!strcasecmp(e->d_name, name)) snprintf(path, n, "%s/%s", dir, e->d_name), found = true;
  closedir(d);
  return found;
}

bool disks_present(const char *dir)
{
  char path[1100];
  return dir && find_in_dir(dir, diskNames[0], path, sizeof path) && find_in_dir(dir, diskNames[1], path, sizeof path);
}

static uint8_t *read_file(const char *path, size_t *len)
{
  FILE *f = fopen(path, "rb");
  if (!f) return NULL;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  uint8_t *d = n > 0 ? malloc((size_t)n) : NULL;
  if (d && fread(d, 1, (size_t)n, f) != (size_t)n) free(d), d = NULL;
  fclose(f);
  *len = d ? (size_t)n : 0;
  return d;
}

// the image's files (its root directory's: not the volume's label, deleted entries, long names' parts or
// subdirectories) added to the table: NULL, or why not
static const char *fat_files(const uint8_t *img, size_t len, DosFile **files, int *count)
{
  if (len < 512) return "not a disk's image (too short)";
  const unsigned bps = rd16(img + 11), spc = img[13], reserved = rd16(img + 14), fats = img[16], entries = rd16(img + 17);
  const unsigned fatSectors = rd16(img + 22);
  const uint32_t sectors = rd16(img + 19) ? rd16(img + 19) : rd32(img + 32);
  if (bps < 128 || bps > 4096 || (bps & (bps - 1)) || !spc || !reserved || !fats || !fatSectors || !entries)
    return "not a FAT disk's image (its boot sector's figures)";
  const size_t fatAt = (size_t)reserved * bps, rootAt = fatAt + (size_t)fats * fatSectors * bps;
  const size_t dataAt = rootAt + ((size_t)entries * 32 + bps - 1) / bps * bps, clusterBytes = (size_t)spc * bps;
  const size_t clusters = (size_t)sectors * bps > dataAt ? ((size_t)sectors * bps - dataAt) / clusterBytes : 0;
  if (rootAt + (size_t)entries * 32 > len || clusters >= 4085) return "not a floppy's FAT12 image";
  for (unsigned e = 0; e < entries; e++)
  {
    const uint8_t *de = img + rootAt + (size_t)e * 32;
    if (de[0] == 0x00) break;  // (the directory's end)
    if (de[0] == 0xE5 || de[0] == '.' || de[11] == 0x0F || (de[11] & 0x18)) continue;
    char name[13];
    int k = 0;
    for (int j = 0; j < 8 && de[j] != ' '; j++) name[k++] = (char)(j == 0 && de[j] == 0x05 ? 0xE5 : de[j]);
    if (de[8] != ' ') name[k++] = '.';
    for (int j = 8; j < 11 && de[j] != ' '; j++) name[k++] = (char)de[j];
    name[k] = 0;
    const uint32_t size = rd32(de + 28);
    if (size > len) return "a file longer than the disk";
    uint8_t *data = malloc(size ? size : 1);
    if (!data) return "no memory for its files";
    uint32_t got = 0;
    for (unsigned c = rd16(de + 26), steps = 0; got < size && c >= 2 && c < clusters + 2 && steps < clusters; steps++)
    {
      const size_t at = dataAt + (size_t)(c - 2) * clusterBytes, fo = fatAt + (size_t)c * 3 / 2;
      if (at >= len || fo + 1 >= len) break;
      size_t n = clusterBytes;
      if (n > size - got) n = size - got;
      if (n > len - at) n = len - at;
      memcpy(data + got, img + at, n);
      got += (uint32_t)n;
      c = c & 1 ? (unsigned)(img[fo] >> 4 | img[fo + 1] << 4) : (unsigned)(img[fo] | (img[fo + 1] & 0x0F) << 8);
    }
    if (got < size) { free(data); return "a file's clusters are missing (a damaged image)"; }
    int at = 0;
    while (at < *count && strcasecmp((*files)[at].name, name)) at++;
    if (at == *count)
    {
      DosFile *more = realloc(*files, (size_t)(*count + 1) * sizeof **files);
      if (!more) { free(data); return "no memory for its files"; }
      *files = more;
      (*count)++;
    }
    else free((*files)[at].data);
    snprintf((*files)[at].name, sizeof (*files)[at].name, "%s", name);
    (*files)[at].data = data;
    (*files)[at].size = size;
  }
  return NULL;
}

int disks_load(const char *dir, DosFile **files, char *err, size_t errSize)
{
  *files = NULL;
  int count = 0;
  for (int k = 0; k < 2; k++)
  {
    char path[1100];
    size_t len = 0;
    uint8_t *img = find_in_dir(dir, diskNames[k], path, sizeof path) ? read_file(path, &len) : NULL;
    const char *why = img ? fat_files(img, len, files, &count) : "cannot be read";
    free(img);
    if (why)
    {
      snprintf(err, errSize, "%s/%s: %s", dir, diskNames[k], why);
      disks_free(*files, count);
      *files = NULL;
      return -1;
    }
  }
  return count;
}

void disks_free(DosFile *files, int count)
{
  for (int k = 0; k < count; k++) free(files[k].data);
  free(files);
}
